        ["S03", "2025-01", 600, "кВт·ч", 3000, 1, "2024-01-01", "базовый"],
        ["S04", "2025-01", 900, "кВт·ч", 4500, 1, "2024-01-01", "базовый"],
        ["S05", "2025-01", 700, "кВт·ч", 3500, 1, "2024-01-01", "базовый"],
